-- Full script: creates football_lab, its tables and view, and loads all the data
ROLLBACK;
-- Football matches lab - normalized schema (3NF)
DROP DATABASE IF EXISTS football_lab;
CREATE DATABASE football_lab CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE football_lab;

CREATE TABLE season (
  season_id  INT AUTO_INCREMENT PRIMARY KEY,
  name       CHAR(5)  NOT NULL,           -- '10/11'
  start_year SMALLINT NOT NULL,           -- 2010
  CONSTRAINT uq_season_name UNIQUE (name)
) ENGINE=InnoDB;

CREATE TABLE team (
  team_id INT AUTO_INCREMENT PRIMARY KEY,
  name    VARCHAR(60) NOT NULL,
  CONSTRAINT uq_team_name UNIQUE (name)
) ENGINE=InnoDB;

CREATE TABLE game (
  game_id   INT PRIMARY KEY,              -- column X of the dataset
  game_date DATE NOT NULL,
  season_id INT  NOT NULL,
  CONSTRAINT fk_game_season FOREIGN KEY (season_id) REFERENCES season (season_id)
) ENGINE=InnoDB;

-- One row per team per game (2 rows per game: home and away)
CREATE TABLE participation (
  team_id         INT NOT NULL,
  game_id         INT NOT NULL,
  side            ENUM('home','away') NOT NULL,
  goals           TINYINT UNSIGNED NOT NULL,
  possession      DECIMAL(4,1)     NOT NULL,
  shots_on_target TINYINT UNSIGNED NOT NULL,
  red_cards       TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (game_id, team_id),
  CONSTRAINT uq_game_side UNIQUE (game_id, side),
  CONSTRAINT fk_participation_game FOREIGN KEY (game_id) REFERENCES game (game_id),
  CONSTRAINT fk_participation_team FOREIGN KEY (team_id) REFERENCES team (team_id),
  CONSTRAINT chk_possession CHECK (possession BETWEEN 0 AND 100)
) ENGINE=InnoDB;

-- Result of each team in each game: 3 points win, 1 draw, 0 loss
CREATE OR REPLACE VIEW team_result AS
SELECT participation.game_id,
       participation.team_id,
       participation.side,
       participation.goals,
       opponent.goals AS goals_against,
       participation.possession,
       CASE WHEN participation.goals > opponent.goals THEN 3
            WHEN participation.goals = opponent.goals THEN 1
            ELSE 0 END AS points
FROM participation
JOIN participation AS opponent
  ON opponent.game_id = participation.game_id
 AND opponent.team_id <> participation.team_id;

USE football_lab;
SET FOREIGN_KEY_CHECKS=0;
TRUNCATE TABLE participation; TRUNCATE TABLE game; TRUNCATE TABLE season; TRUNCATE TABLE team;
SET FOREIGN_KEY_CHECKS=1;
START TRANSACTION;





























COMMIT;

SELECT 'team' AS table_name, COUNT(*) AS row_count FROM team
UNION ALL SELECT 'season', COUNT(*) FROM season
UNION ALL SELECT 'game', COUNT(*) FROM game
UNION ALL SELECT 'participation', COUNT(*) FROM participation;
